    }

    return results;
}

// ==================== OUTPUT FORMATTING ====================

class OutputFormatter {
public:
    const Settings& settings;
    std::ostream& errOut;

    OutputFormatter(const Settings& s, std::ostream& err) : settings(s), errOut(err) {}

    std::string formatMessage(const CheckResult& r) const {
        if (!settings.templateStr.empty()) {
            return formatWithTemplate(r, settings.templateStr);
        }
        // Default gcc format: [file:line]: (severity) message
        return "[" + r.filename + ":" + std::to_string(r.line) + "]: (" + r.severity + ") " + r.message;
    }

    std::string formatWithTemplate(const CheckResult& r, const std::string& tmpl) const {
        std::string result = tmpl;
        auto replaceAll = [&](const std::string& from, const std::string& to) {
            size_t pos = 0;
            while ((pos = result.find(from, pos)) != std::string::npos) {
                result.replace(pos, from.length(), to);
                pos += to.length();
            }
        };

        replaceAll("{file}", r.filename);
        replaceAll("{line}", std::to_string(r.line));
        replaceAll("{column}", std::to_string(r.col));
        replaceAll("{severity}", r.severity);
        replaceAll("{message}", r.message);
        replaceAll("{id}", r.id);
        replaceAll("{callstack}", "[" + r.filename + ":" + std::to_string(r.line) + "]");
        replaceAll("{code}", "");
        replaceAll("{inconclusive:text}", "");
        replaceAll("{cwe}", "");

        // Handle escape sequences
        std::string final_result;
        for (size_t i = 0; i < result.size(); i++) {
            if (result[i] == '\\' && i+1 < result.size()) {
                if (result[i+1] == 'n') { final_result += '\n'; i++; }
                else if (result[i+1] == 't') { final_result += '\t'; i++; }
                else if (result[i+1] == 'r') { final_result += '\r'; i++; }
                else { final_result += result[i]; }
            } else {
                final_result += result[i];
            }
        }
        return final_result;
    }

    void outputError(const CheckResult& r) {
        if (settings.xml) {
            std::string loc = "<location file=\"" + xmlEncode(r.filename) + 
                             "\" line=\"" + std::to_string(r.line) + "\"";
            if (r.col > 0) loc += " column=\"" + std::to_string(r.col) + "\"";
            loc += "/>";

            errOut << "    <error id=\"" << xmlEncode(r.id) << "\""
                   << " severity=\"" << xmlEncode(r.severity) << "\""
                   << " msg=\"" << xmlEncode(r.message) << "\""
                   << " verbose=\"" << xmlEncode(r.verbose.empty() ? r.message : r.verbose) << "\">\n"
                   << "        " << loc << "\n"
                   << "    </error>\n";
        } else {
            errOut << formatMessage(r) << "\n";
        }
    }

    void beginXml() {
        if (settings.xml) {
            errOut << "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
            errOut << "<results version=\"2\">\n";
            errOut << "    <cppcheck version=\"" << CPPCHECK_VERSION_STRING << "\"/>\n";
            errOut << "    <errors>\n";
        }
    }

    void endXml() {
        if (settings.xml) {
            errOut << "    </errors>\n";
            errOut << "</results>\n";
        }
    }
};

// ==================== FILE LOADING ====================

static bool loadCfgFile(const std::string& name, const Settings& settings) {
    // Try FILESDIR/cfg/name.cfg
    std::string path = std::string(FILESDIR) + "/cfg/" + name + ".cfg";
    std::ifstream f(path);
    if (!f.is_open()) {
        // Try just name
        f.open(name);
        if (!f.is_open()) return false;
    }
    return true;
}

static bool checkStdCfg() {
    std::string path = std::string(FILESDIR) + "/cfg/std.cfg";
    std::ifstream f(path);
    return f.is_open();
}

// ==================== MAIN CHECKER ====================

class CppCheck {
public:
    Settings settings;
    std::ostream* errStream = nullptr;
    std::ostream* outStream = nullptr;
    bool hasErrors = false;
    int numErrors = 0;

    int check(const std::string& filename) {
        // Read file
        std::ifstream f(filename);
        if (!f.is_open()) {
            if (!settings.quiet) {
                *errStream << "cppcheck: error: could not open file: " << filename << std::endl;
            }
            return 0;
        }

        std::string code((std::istreambuf_iterator<char>(f)),
                          std::istreambuf_iterator<char>());

        // Run checks
        auto results = runChecks(filename, code, settings);

        OutputFormatter formatter(settings, *errStream);
        for (const auto& r : results) {
            if (settings.isEnabled(r.severity)) {
                formatter.outputError(r);
                hasErrors = true;
                numErrors++;
            }
        }

        return results.size();
    }
};

// ==================== PROGRESS REPORTING ====================

static void reportProgress(std::ostream& out, const std::string& filename,
                           int current, int total) {
    out << "Checking " << filename << "...\n";
    if (total > 1) {
        int pct = (current * 100) / total;
        out << current << "/" << total << " files checked " << pct << "% done\n";
    }
    out.flush();
}

// ==================== DIRECTORY SCANNING ====================

static std::vector<std::string> getSourceFiles(const std::string& path) {
    std::vector<std::string> files;

    static const std::set<std::string> extensions = {
        ".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx"
    };

    try {
        if (fs::is_regular_file(path)) {
            files.push_back(path);
        } else if (fs::is_directory(path)) {
            for (auto& entry : fs::recursive_directory_iterator(path)) {
                if (entry.is_regular_file()) {
                    std::string ext = entry.path().extension().string();
                    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
                    if (extensions.count(ext)) {
                        files.push_back(entry.path().string());
                    }
                }
            }
            std::sort(files.begin(), files.end());
        }
    } catch (const std::exception&) {}

    return files;
}

