// ==================== MAIN CHECKER ====================

class CppCheck {
public:
    Settings settings;
    std::ostream* errStream = nullptr;
    std::ostream* outStream = nullptr;
    bool hasErrors = false;
    int numErrors = 0;

    int check(const std::string& filename) {
        // Read file
        std::ifstream f(filename);
        if (!f.is_open()) {
            if (!settings.quiet) {
                *errStream << "cppcheck: error: could not open file: " << filename << std::endl;
            }
            return 0;
        }

        std::string code((std::istreambuf_iterator<char>(f)),
                          std::istreambuf_iterator<char>());

        // Run checks
        auto results = runChecks(filename, code, settings);

        OutputFormatter formatter(settings, *errStream);
        for (const auto& r : results) {
            if (settings.isEnabled(r.severity)) {
                formatter.outputError(r);
                hasErrors = true;
                numErrors++;
            }
        }

        return results.size();
    }
};

// ==================== PROGRESS REPORTING ====================

static void reportProgress(std::ostream& out, const std::string& filename,
                           int current, int total) {
    out << "Checking " << filename << "...\n";
    if (total > 1) {
        int pct = (current * 100) / total;
        out << current << "/" << total << " files checked " << pct << "% done\n";
    }
    out.flush();
}

// ==================== DIRECTORY SCANNING ====================

static std::vector<std::string> getSourceFiles(const std::string& path) {
    std::vector<std::string> files;

    static const std::set<std::string> extensions = {
        ".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx"
    };

    try {
        if (fs::is_regular_file(path)) {
            files.push_back(path);
        } else if (fs::is_directory(path)) {
            for (auto& entry : fs::recursive_directory_iterator(path)) {
                if (entry.is_regular_file()) {
                    std::string ext = entry.path().extension().string();
                    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
                    if (extensions.count(ext)) {
                        files.push_back(entry.path().string());
                    }
                }
            }
            std::sort(files.begin(), files.end());
        }
    } catch (const std::exception&) {}

    return files;
}

