    std::string templateLocationStr;
    std::string cppcheckBuildDir;
    std::string projectFile;
    std::string clangPath;

    std::vector<std::string> includePaths;
    std::vector<std::string> libraries;
    std::vector<std::string> defines;
    std::vector<std::string> undefines;
    std::vector<std::string> suppressions;
    std::vector<std::string> fileFilters;
    std::vector<std::string> ignorePaths;
    std::vector<std::string> configExcludes;

    // Enabled checks
    std::set<std::string> enabledChecks;
    std::set<std::string> disabledChecks;

    // Standards
    std::string cStd = "c11";
    std::string cppStd = "c++20";

    std::string reportType = "normal";

    bool isEnabled(const std::string& severity) const {
        if (disabledChecks.count(severity)) return false;
        if (severity == "error") return true;
        return enabledChecks.count(severity) > 0 || enabledChecks.count("all") > 0;
    }

    void enableAll() {
        enabledChecks.insert("warning");
        enabledChecks.insert("style");
