};

// ==================== TOKENIZER ====================

enum class TokenType {
    NONE,
    KEYWORD,
    IDENTIFIER,
    NUMBER,
    STRING,
    CHAR,
    OPERATOR,
    PUNCTUATION,
    PREPROCESSOR,
    COMMENT,
    NEWLINE,
    UNKNOWN
};

struct Token {
    std::string str;
    TokenType type;
    int line;
    int col;

    Token() : type(TokenType::NONE), line(0), col(0) {}
    Token(const std::string& s, TokenType t, int l, int c)
        : str(s), type(t), line(l), col(c) {}

    bool isName() const {
        return type == TokenType::IDENTIFIER || type == TokenType::KEYWORD;
    }

    bool isNumber() const {
        return type == TokenType::NUMBER;
    }

    bool isKeyword() const {
        return type == TokenType::KEYWORD;
    }
};

static const std::set<std::string> KEYWORDS = {
    "auto", "break", "case", "char", "const", "continue", "default", "do",
    "double", "else", "enum", "extern", "float", "for", "goto", "if",
    "inline", "int", "long", "register", "restrict", "return", "short",
    "signed", "sizeof", "static", "struct", "switch", "typedef", "union",
    "unsigned", "void", "volatile", "while",
    // C99/C11
    "_Bool", "_Complex", "_Imaginary", "_Alignas", "_Alignof", "_Atomic",
    "_Generic", "_Noreturn", "_Static_assert", "_Thread_local",
    // C++
    "bool", "catch", "class", "delete", "explicit", "export", "false",
    "friend", "mutable", "namespace", "new", "operator", "private",
    "protected", "public", "template", "this", "throw", "true", "try",
    "typeid", "typename", "using", "virtual", "wchar_t",
    // C++11
    "alignas", "alignof", "char16_t", "char32_t", "constexpr", "decltype",
    "final", "noexcept", "nullptr", "override", "static_assert",
    "thread_local", "char8_t"
};

class Tokenizer {
public:
    std::vector<Token> tokens;
    std::string filename;

    bool tokenize(const std::string& code, const std::string& fname) {
        filename = fname;
        tokens.clear();

        size_t i = 0;
        int line = 1;
        int col = 1;

        while (i < code.size()) {
            // Skip whitespace
            if (code[i] == ' ' || code[i] == '\t' || code[i] == '\r') {
                col++;
                i++;
                continue;
            }

            if (code[i] == '\n') {
                line++;
                col = 1;
                i++;
                continue;
            }

            // Preprocessor directive
            if (code[i] == '#') {
                int startLine = line;
                int startCol = col;
                std::string directive;
                while (i < code.size() && code[i] != '\n') {
                    // Handle line continuation
                    if (code[i] == '\\' && i+1 < code.size() && code[i+1] == '\n') {
                        directive += ' ';
                        i += 2;
                        line++;
                        col = 1;
                        continue;
                    }
                    directive += code[i];
                    i++;
                    col++;
                }
                tokens.emplace_back(directive, TokenType::PREPROCESSOR, startLine, startCol);
                continue;
            }

            // Comments
            if (code[i] == '/' && i+1 < code.size()) {
                if (code[i+1] == '/') {
                    // Line comment
                    while (i < code.size() && code[i] != '\n') { i++; col++; }
                    continue;
                }
                if (code[i+1] == '*') {
                    // Block comment
                    i += 2; col += 2;
                    while (i < code.size()) {
                        if (code[i] == '\n') { line++; col = 1; i++; }
                        else if (code[i] == '*' && i+1 < code.size() && code[i+1] == '/') {
                            i += 2; col += 2;
                            break;
                        } else { i++; col++; }
                    }
                    continue;
                }
            }

            // String literals
            if (code[i] == '"' || (code[i] == 'L' && i+1 < code.size() && code[i+1] == '"') ||
                (code[i] == 'u' && i+1 < code.size() && code[i+1] == '"') ||
                (code[i] == 'U' && i+1 < code.size() && code[i+1] == '"')) {
                int startLine = line;
                int startCol = col;
                std::string s;
                if (code[i] != '"') { s += code[i]; i++; col++; }
                s += '"'; i++; col++;
                while (i < code.size() && code[i] != '"') {
                    if (code[i] == '\\') { 
                        s += code[i]; i++; col++;
                        if (i < code.size()) { s += code[i]; i++; col++; }
                    } else if (code[i] == '\n') {
                        line++; col = 1;
                        s += code[i]; i++;
                    } else {
                        s += code[i]; i++; col++;
                    }
                }
                if (i < code.size()) { s += '"'; i++; col++; }
                tokens.emplace_back(s, TokenType::STRING, startLine, startCol);
                continue;
            }

            // Char literals
            if (code[i] == '\'' || (code[i] == 'L' && i+1 < code.size() && code[i+1] == '\'')) {
                int startLine = line;
                int startCol = col;
                std::string s;
                if (code[i] != '\'') { s += code[i]; i++; col++; }
                s += '\''; i++; col++;
                while (i < code.size() && code[i] != '\'') {
                    if (code[i] == '\\') {
                        s += code[i]; i++; col++;
                        if (i < code.size()) { s += code[i]; i++; col++; }
                    } else { s += code[i]; i++; col++; }
                }
                if (i < code.size()) { s += '\''; i++; col++; }
                tokens.emplace_back(s, TokenType::CHAR, startLine, startCol);
                continue;
            }

            // Numbers
            if (isdigit(code[i]) || (code[i] == '.' && i+1 < code.size() && isdigit(code[i+1]))) {
                int startLine = line;
                int startCol = col;
                std::string s;
                while (i < code.size() && (isalnum(code[i]) || code[i] == '.' || code[i] == '_' ||
                       ((code[i] == '+' || code[i] == '-') && i > 0 && (code[i-1] == 'e' || code[i-1] == 'E')))) {
                    s += code[i]; i++; col++;
                }
                tokens.emplace_back(s, TokenType::NUMBER, startLine, startCol);
                continue;
            }

            // Identifiers and keywords
            if (isalpha(code[i]) || code[i] == '_') {
                int startLine = line;
                int startCol = col;
                std::string s;
                while (i < code.size() && (isalnum(code[i]) || code[i] == '_')) {
                    s += code[i]; i++; col++;
                }
                TokenType t = KEYWORDS.count(s) ? TokenType::KEYWORD : TokenType::IDENTIFIER;
                tokens.emplace_back(s, t, startLine, startCol);
                continue;
            }

            // Multi-char operators
            int startLine = line;
            int startCol = col;
            std::string op;
            op += code[i];

            if (i+1 < code.size()) {
                std::string twoChar = op + code[i+1];
                if (twoChar == "==" || twoChar == "!=" || twoChar == "<=" || twoChar == ">=" ||
                    twoChar == "&&" || twoChar == "||" || twoChar == "++" || twoChar == "--" ||
                    twoChar == "+=" || twoChar == "-=" || twoChar == "*=" || twoChar == "/=" ||
                    twoChar == "%=" || twoChar == "&=" || twoChar == "|=" || twoChar == "^=" ||
                    twoChar == "<<" || twoChar == ">>" || twoChar == "->" || twoChar == "::" ||
                    twoChar == "##") {
                    op = twoChar;
                    i += 2; col += 2;
                    // Check for three-char
                    if (i < code.size()) {
                        std::string threeChar = op + code[i];
                        if (threeChar == "<<=" || threeChar == ">>=") {
                            op = threeChar;
                            i++; col++;
                        }
                    }
                    tokens.emplace_back(op, TokenType::OPERATOR, startLine, startCol);
                    continue;
                }
            }

            // Single char operators/punctuation
            bool isPunct = (code[i] == '(' || code[i] == ')' || code[i] == '{' || 
                           code[i] == '}' || code[i] == '[' || code[i] == ']' ||
                           code[i] == ';' || code[i] == ',' || code[i] == '.' ||
                           code[i] == ':' || code[i] == '?');
            TokenType tokenType = isPunct ? TokenType::PUNCTUATION : TokenType::OPERATOR;
            tokens.emplace_back(std::string(1, code[i]), tokenType, startLine, startCol);
            i++; col++;
        }

        return true;
    }
};

// ==================== CHECKS ====================

struct CheckResult {
    std::string filename;
    int line;
    int col;
    std::string id;
    std::string severity;
    std::string message;
    std::string verbose;

    CheckResult() : line(0), col(0) {}
    CheckResult(const std::string& f, int l, const std::string& id_,
                const std::string& sev, const std::string& msg, const std::string& verb = "")
        : filename(f), line(l), col(0), id(id_), severity(sev), message(msg), verbose(verb) {}
};

// Check for array out of bounds
static void checkArrayBounds(const Tokenizer& tokenizer, std::vector<CheckResult>& results) {
    const auto& tokens = tokenizer.tokens;

    // Find array declarations: type name[size]
    // Simple pattern matching
    struct ArrayInfo {
        std::string name;
        long long size;
        int line;
    };

    std::vector<ArrayInfo> arrays;
    std::map<std::string, long long> arrayMap;

    for (size_t i = 0; i < tokens.size(); i++) {
        // Look for: type name[N]
        if (tokens[i].isName() && i+1 < tokens.size() && tokens[i+1].str == "[") {
            // Could be declaration or access
            // Check if it's a declaration (preceded by type name)
            if (i >= 1 && tokens[i-1].isName()) {
                // type name[N] - could be array declaration
                if (i+2 < tokens.size() && tokens[i+2].isNumber() && 
                    i+3 < tokens.size() && tokens[i+3].str == "]") {
                    // Check it's followed by ; or , or ) or =
                    size_t j = i+4;
                    while (j < tokens.size() && tokens[j].str == "*") j++;
                    if (j < tokens.size() && (tokens[j].str == ";" || tokens[j].str == "," ||
                        tokens[j].str == ")" || tokens[j].str == "=" || 
                        tokens[j].str == "[")) {
                        try {
                            long long sz = std::stoll(tokens[i+2].str);
                            ArrayInfo ai;
                            ai.name = tokens[i].str;
                            ai.size = sz;
                            ai.line = tokens[i].line;
                            arrays.push_back(ai);
                            arrayMap[tokens[i].str] = sz;
                        } catch (...) {}
                    }
                }
            }
        }
    }

    // Now look for array access with constant index
    for (size_t i = 0; i < tokens.size(); i++) {
        if (tokens[i].isName() && i+1 < tokens.size() && tokens[i+1].str == "[" &&
            i+2 < tokens.size() && tokens[i+2].isNumber() &&
            i+3 < tokens.size() && tokens[i+3].str == "]") {

            auto it = arrayMap.find(tokens[i].str);
            if (it != arrayMap.end()) {
                try {
                    long long idx = std::stoll(tokens[i+2].str);
                    long long sz = it->second;
                    if (idx >= sz || idx < 0) {
                        std::string msg = "Array '" + tokens[i].str + "[" + std::to_string(sz) + 
                            "]' index " + std::to_string(idx) + " out of bounds";
                        results.emplace_back(tokenizer.filename, tokens[i].line,
                            "arrayIndexOutOfBounds", "error", msg, msg);
                    }
                } catch (...) {}
            }
        }
    }
}

// Check for null pointer dereference
static void checkNullPointer(const Tokenizer& tokenizer, std::vector<CheckResult>& results) {
    const auto& tokens = tokenizer.tokens;

    // Simple patterns:
    // p = 0; *p -> null deref
    // p = NULL; *p -> null deref

    std::map<std::string, int> nullPtrs; // name -> assignment line

    for (size_t i = 0; i < tokens.size(); i++) {
        // Assignment: name = 0; or name = NULL;
        if (tokens[i].isName() && i+1 < tokens.size() && tokens[i+1].str == "=" &&
            i+2 < tokens.size() && i+3 < tokens.size()) {
            if ((tokens[i+2].str == "0" || tokens[i+2].str == "NULL" || tokens[i+2].str == "nullptr") &&
                tokens[i+3].str == ";") {
                nullPtrs[tokens[i].str] = tokens[i].line;
            } else {
                // Assignment to non-null, remove from set
                nullPtrs.erase(tokens[i].str);
            }
        }

        // Dereference: *name or name->
        if (tokens[i].str == "*" && i+1 < tokens.size() && tokens[i+1].isName()) {
            auto it = nullPtrs.find(tokens[i+1].str);
            if (it != nullPtrs.end()) {
                std::string msg = "Null pointer dereference: " + tokens[i+1].str;
                results.emplace_back(tokenizer.filename, tokens[i].line,
                    "nullPointer", "error", msg, msg);
            }
        }

        // -> operator
        if (tokens[i].isName() && i+1 < tokens.size() && tokens[i+1].str == "->") {
            auto it = nullPtrs.find(tokens[i].str);
            if (it != nullPtrs.end()) {
                std::string msg = "Null pointer dereference: " + tokens[i].str;
                results.emplace_back(tokenizer.filename, tokens[i].line,
                    "nullPointer", "error", msg, msg);
            }
        }
    }
}

