    // Try FILESDIR/cfg/name.cfg
    std::string path1 = std::string(FILESDIR) + "/cfg/" + name;
    std::string path2 = std::string(FILESDIR) + "/cfg/" + name + ".cfg";

    std::ifstream f1(path1);
    if (f1.is_open()) return true;

    std::ifstream f2(path2);
    if (f2.is_open()) return true;

    // Try as absolute path
    if (name[0] == '/') {
        std::ifstream f3(name);
        if (f3.is_open()) return true;
    }

    return false;
}

