// ==================== TOKENIZER ====================

enum class TokType {
    NONE, KEYWORD, NAME, NUMBER, STRING, CHARLIT, OP, PUNCT, PREPROCESSOR
};

struct Token {
    std::string str;
    TokType type;
    int line, col;
    const Token* next;
    const Token* previous;

    Token() : type(TokType::NONE), line(0), col(0), next(nullptr), previous(nullptr) {}

    bool isName() const { return type == TokType::NAME || type == TokType::KEYWORD; }
    bool isNumber() const { return type == TokType::NUMBER; }
    bool isOp() const { return type == TokType::OP; }
    bool isPunct() const { return type == TokType::PUNCT; }

    long long getNumber() const {
        try {
            if (str.size() > 2 && str[0] == '0' && (str[1] == 'x' || str[1] == 'X'))
                return (long long)std::stoll(str, nullptr, 16);
            return std::stoll(str);
        } catch (...) { return 0; }
    }
};

static const std::set<std::string> KEYWORDS_SET = {
    "auto", "break", "case", "char", "const", "continue", "default", "do",
    "double", "else", "enum", "extern", "float", "for", "goto", "if",
    "inline", "int", "long", "register", "restrict", "return", "short",
    "signed", "sizeof", "static", "struct", "switch", "typedef", "union",
    "unsigned", "void", "volatile", "while",
    "_Bool", "_Complex", "_Imaginary", "_Alignas", "_Alignof", "_Atomic",
    "_Generic", "_Noreturn", "_Static_assert", "_Thread_local",
    "bool", "catch", "class", "delete", "explicit", "export", "false",
    "friend", "mutable", "namespace", "new", "operator", "private",
    "protected", "public", "template", "this", "throw", "true", "try",
    "typeid", "typename", "using", "virtual", "wchar_t",
    "alignas", "alignof", "char16_t", "char32_t", "constexpr", "decltype",
    "final", "noexcept", "nullptr", "override", "static_assert",
    "thread_local", "char8_t", "co_await", "co_return", "co_yield",
    "concept", "requires", "consteval", "constinit", "export", "import",
    "module"
};

class TokenList {
public:
    std::vector<Token> tokens;
    std::string filename;

    bool tokenize(const std::string& code, const std::string& fname) {
        filename = fname;
        tokens.clear();

        size_t i = 0;
        size_t n = code.size();
        int line = 1, col = 1;

        auto addTok = [&](const std::string& s, TokType t, int l, int c) {
            Token tok;
            tok.str = s;
            tok.type = t;
            tok.line = l;
            tok.col = c;
            tokens.push_back(tok);
        };

        while (i < n) {
            char c = code[i];

            if (c == '\n') { line++; col = 1; i++; continue; }
            if (c == '\r') { i++; continue; }
            if (c == ' ' || c == '\t') { col++; i++; continue; }

            int startLine = line, startCol = col;

            // Preprocessor
            if (c == '#') {
                std::string directive;
                while (i < n && code[i] != '\n') {
                    if (code[i] == '\\' && i+1 < n && code[i+1] == '\n') {
                        directive += ' ';
                        i += 2; line++; col = 1;
                    } else {
                        directive += code[i]; i++; col++;
                    }
                }
                addTok(directive, TokType::PREPROCESSOR, startLine, startCol);
                continue;
            }

            // Line comment
            if (c == '/' && i+1 < n && code[i+1] == '/') {
                while (i < n && code[i] != '\n') { i++; col++; }
                continue;
            }

            // Block comment
            if (c == '/' && i+1 < n && code[i+1] == '*') {
                i += 2; col += 2;
                while (i < n) {
                    if (code[i] == '\n') { line++; col = 1; i++; }
                    else if (code[i] == '*' && i+1 < n && code[i+1] == '/') { i += 2; col += 2; break; }
                    else { i++; col++; }
                }
                continue;
            }

            // String literal (handle various prefixes)
            if (c == '"' || 
                ((c == 'u' || c == 'U' || c == 'L') && i+1 < n && code[i+1] == '"') ||
                (c == 'u' && i+1 < n && code[i+1] == '8' && i+2 < n && code[i+2] == '"')) {
                std::string s;
                while (i < n && code[i] != '"') { s += code[i]; i++; col++; }
                s += '"'; i++; col++;
                while (i < n) {
                    if (code[i] == '\\' && i+1 < n) {
                        s += code[i]; s += code[i+1]; i += 2; col += 2;
                    } else if (code[i] == '"') {
                        s += '"'; i++; col++; break;
                    } else if (code[i] == '\n') {
                        line++; col = 1; s += code[i]; i++;
                    } else {
                        s += code[i]; i++; col++;
                    }
                }
                addTok(s, TokType::STRING, startLine, startCol);
                continue;
            }

            // Char literal
            if (c == '\'' || ((c == 'u' || c == 'U' || c == 'L') && i+1 < n && code[i+1] == '\'')) {
                std::string s;
                while (i < n && code[i] != '\'') { s += code[i]; i++; col++; }
                s += '\''; i++; col++;
                while (i < n) {
                    if (code[i] == '\\' && i+1 < n) {
                        s += code[i]; s += code[i+1]; i += 2; col += 2;
                    } else if (code[i] == '\'') {
                        s += '\''; i++; col++; break;
                    } else {
                        s += code[i]; i++; col++;
                    }
                }
                addTok(s, TokType::CHARLIT, startLine, startCol);
                continue;
            }

            // Number
            if (isdigit(c) || (c == '.' && i+1 < n && isdigit(code[i+1]))) {
                std::string s;
                // Hex
                if (c == '0' && i+1 < n && (code[i+1] == 'x' || code[i+1] == 'X')) {
                    s += code[i]; s += code[i+1]; i += 2; col += 2;
                    while (i < n && isxdigit(code[i])) { s += code[i]; i++; col++; }
                } else {
                    while (i < n && (isalnum(code[i]) || code[i] == '.' || code[i] == '_')) {
                        s += code[i]; i++; col++;
                    }
                    // Handle exponent
                    if (i < n && (code[i] == 'e' || code[i] == 'E')) {
                        s += code[i]; i++; col++;
                        if (i < n && (code[i] == '+' || code[i] == '-')) { s += code[i]; i++; col++; }
                        while (i < n && isdigit(code[i])) { s += code[i]; i++; col++; }
                    }
                    // Suffixes
                    while (i < n && (code[i] == 'u' || code[i] == 'U' || code[i] == 'l' || code[i] == 'L' || code[i] == 'f' || code[i] == 'F')) {
                        s += code[i]; i++; col++;
                    }
                }
                addTok(s, TokType::NUMBER, startLine, startCol);
                continue;
            }

            // Identifier/keyword
            if (isalpha(c) || c == '_') {
                std::string s;
                while (i < n && (isalnum(code[i]) || code[i] == '_')) {
                    s += code[i]; i++; col++;
                }
                TokType t = KEYWORDS_SET.count(s) ? TokType::KEYWORD : TokType::NAME;
                addTok(s, t, startLine, startCol);
                continue;
            }

            // Operators (multi-char)
            {
                std::string op(1, c);
                col++; i++;

                if (i < n) {
                    std::string two = op + code[i];
                    static const std::set<std::string> twoCharOps = {
                        "==", "!=", "<=", ">=", "&&", "||", "++", "--",
                        "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=",
                        "<<", ">>", "->", "::", "##", "..", "/*", "*/"
                    };
                    if (twoCharOps.count(two)) {
                        op = two; col++; i++;
                        if (i < n) {
                            std::string three = op + code[i];
                            if (three == "<<=" || three == ">>=") {
                                op = three; col++; i++;
                            } else if (three == "...") {
                                op = three; col++; i++;
                            }
                        }
                    }
                }

                bool isPunct = (op == "(" || op == ")" || op == "{" || op == "}" ||
                                op == "[" || op == "]" || op == ";" || op == "," ||
                                op == "." || op == ":" || op == "?");
                addTok(op, isPunct ? TokType::PUNCT : TokType::OP, startLine, startCol);
            }
        }

        // Link tokens
        for (size_t j = 0; j < tokens.size(); j++) {
            tokens[j].next = (j+1 < tokens.size()) ? &tokens[j+1] : nullptr;
            tokens[j].previous = (j > 0) ? &tokens[j-1] : nullptr;
        }

        return true;
    }

    const Token* front() const { return tokens.empty() ? nullptr : &tokens[0]; }
};

// ==================== CHECKS ====================

static void checkArrayOutOfBounds(const TokenList& tl, std::vector<ErrorResult>& results) {
    const auto& toks = tl.tokens;

    // Track array declarations: name -> size
    std::map<std::string, long long> arrays;

    // Find declarations: type name[size];
    for (size_t i = 0; i < toks.size(); i++) {
        // Look for: NAME '[' NUMBER ']' optionally followed by ';' or '='
        if (toks[i].isName() && i+3 < toks.size() &&
            toks[i+1].str == "[" && toks[i+2].isNumber() && toks[i+3].str == "]") {

            // Check if it's a declaration (type precedes the name)
            if (i >= 1 && (toks[i-1].isName() || toks[i-1].str == "*")) {
                try {
                    long long sz = toks[i+2].getNumber();
                    if (sz > 0) {
                        arrays[toks[i].str] = sz;
                    }
                } catch (...) {}
            }
        }
    }

    // Check array accesses
    for (size_t i = 0; i < toks.size(); i++) {
        if (toks[i].isName() && i+3 < toks.size() &&
            toks[i+1].str == "[" && toks[i+2].isNumber() && toks[i+3].str == "]") {

            auto it = arrays.find(toks[i].str);
            if (it != arrays.end()) {
                try {
                    long long idx = toks[i+2].getNumber();
                    long long sz = it->second;
                    if (idx < 0 || idx >= sz) {
                        ErrorResult err;
                        err.id = "arrayIndexOutOfBounds";
                        err.severity = "error";
                        err.message = "Array '" + toks[i].str + "[" + std::to_string(sz) + 
                                     "]' index " + std::to_string(idx) + " out of bounds";
                        err.verbose = err.message;
                        err.cwe = "788";
                        err.addLocation(tl.filename, toks[i].line, toks[i].col);
                        results.push_back(err);
                    }
                } catch (...) {}
            }
        }
    }
}

static void checkNullPointerDeref(const TokenList& tl, std::vector<ErrorResult>& results) {
    const auto& toks = tl.tokens;

    // Track known null pointers within the current scope
    std::map<std::string, int> nullPtrs; // name -> line where assigned null

    for (size_t i = 0; i < toks.size(); i++) {
        const auto& t = toks[i];

        // Assignment to null: name = 0/NULL/nullptr;
        if (t.isName() && i+3 < toks.size() && toks[i+1].str == "=") {
            const std::string& val = toks[i+2].str;
            if ((val == "0" || val == "NULL" || val == "nullptr") && 
                toks[i+3].str == ";") {
                nullPtrs[t.str] = t.line;
            } else if (toks[i+1].str == "=" && val != "=" && !(val == "0" || val == "NULL" || val == "nullptr")) {
                // Assigned something non-null
                nullPtrs.erase(t.str);
            }
        }

        // Dereference: *ptr or ptr->
        if (t.str == "*" && i+1 < toks.size() && toks[i+1].isName()) {
            auto it = nullPtrs.find(toks[i+1].str);
            if (it != nullPtrs.end()) {
                ErrorResult err;
                err.id = "nullPointer";
                err.severity = "error";
                err.message = "Null pointer dereference: " + toks[i+1].str;
                err.verbose = err.message;
                err.cwe = "476";
                err.addLocation(tl.filename, t.line, t.col);
                results.push_back(err);
            }
        }

        if (t.isName() && i+1 < toks.size() && toks[i+1].str == "->") {
            auto it = nullPtrs.find(t.str);
            if (it != nullPtrs.end()) {
                ErrorResult err;
                err.id = "nullPointer";
                err.severity = "error";
                err.message = "Null pointer dereference: " + t.str;
                err.verbose = err.message;
                err.cwe = "476";
                err.addLocation(tl.filename, t.line, t.col);
                results.push_back(err);
            }
        }
    }
}

static std::vector<ErrorResult> runAllChecks(const std::string& filename, 
                                              const std::string& code,
                                              const Settings& settings) {
    std::vector<ErrorResult> results;

    TokenList tl;
    if (!tl.tokenize(code, filename)) {
        return results;
    }

    // Error-level checks (always enabled)
    checkArrayOutOfBounds(tl, results);
    checkNullPointerDeref(tl, results);

    return results;
}

// ==================== OUTPUT ====================

static std::string makeGccFormat(const ErrorResult& r) {
    std::string loc;
    if (!r.locations.empty()) {
        loc = r.locations[0].file + ":" + std::to_string(r.locations[0].line) + ":";
        if (r.locations[0].col > 0)
            loc += std::to_string(r.locations[0].col) + ":";
        else
            loc += "0:";
    } else {
        loc = ":0:0:";
    }

    std::string inconclusive_str = r.inconclusive ? " inconclusive" : "";
    std::string result = loc + " " + r.severity + inconclusive_str + ": " + r.message + " [" + r.id + "]";
    return result;
}

static std::string makeCppcheck1Format(const ErrorResult& r) {
    std::string loc;
    if (!r.locations.empty()) {
        loc = "[" + r.locations[0].file + ":" + std::to_string(r.locations[0].line) + "]";
    }
    std::string inconclusive_str = r.inconclusive ? " inconclusive" : "";
    return loc + ": (" + r.severity + inconclusive_str + ") " + r.message;
}

static std::string makeVsFormat(const ErrorResult& r) {
    std::string loc;
    if (!r.locations.empty()) {
        loc = r.locations[0].file + "(" + std::to_string(r.locations[0].line) + ")";
    }
    return loc + ": error " + r.id + ": " + r.message;
}

static std::string applyTemplate(const std::string& tmpl, const ErrorResult& r) {
    std::string result = tmpl;

    auto replaceAll = [&](const std::string& from, const std::string& to) {
        size_t pos = 0;
        while ((pos = result.find(from, pos)) != std::string::npos) {
            result.replace(pos, from.length(), to);
            pos += to.length();
        }
    };

    std::string file, lineStr, colStr;
    if (!r.locations.empty()) {
        file = r.locations[0].file;
        lineStr = std::to_string(r.locations[0].line);
        colStr = std::to_string(r.locations[0].col);
    }

    // Handle {inconclusive:text}
    size_t inconPos = result.find("{inconclusive:");
    while (inconPos != std::string::npos) {
        size_t endPos = result.find("}", inconPos);
        if (endPos == std::string::npos) break;
        std::string incText = result.substr(inconPos + 14, endPos - inconPos - 14);
        result.replace(inconPos, endPos - inconPos + 1, r.inconclusive ? incText : "");
        inconPos = result.find("{inconclusive:", inconPos);
    }

    replaceAll("{file}", file);
    replaceAll("{line}", lineStr);
    replaceAll("{column}", colStr);
    replaceAll("{severity}", r.severity);
    replaceAll("{message}", r.message);
    replaceAll("{id}", r.id);
    replaceAll("{cwe}", r.cwe);
    replaceAll("{code}", "");

    // Callstack
    std::string callstack;
    for (size_t i = 0; i < r.locations.size(); i++) {
        if (i > 0) callstack += " -> ";
        callstack += "[" + r.locations[i].file + ":" + std::to_string(r.locations[i].line) + "]";
    }
    replaceAll("{callstack}", callstack);

    // Escape sequences
    std::string final_result;
    for (size_t j = 0; j < result.size(); j++) {
        if (result[j] == '\\' && j+1 < result.size()) {
            if (result[j+1] == 'n') { final_result += '\n'; j++; }
            else if (result[j+1] == 't') { final_result += '\t'; j++; }
            else if (result[j+1] == 'r') { final_result += '\r'; j++; }
            else { final_result += result[j]; }
        } else {
            final_result += result[j];
        }
    }
    return final_result;
}

static std::string formatError(const ErrorResult& r, const Settings& settings) {
    if (settings.templateStr.empty()) {
        // Default: gcc format
        return makeGccFormat(r);
    }

    const std::string& tmpl = settings.templateStr;
    if (tmpl == "gcc") return makeGccFormat(r);
    if (tmpl == "cppcheck1") return makeCppcheck1Format(r);
    if (tmpl == "vs") return makeVsFormat(r);
    if (tmpl == "edit") {
        // edit format: file:line:col: (severity) message
        std::string loc;
        if (!r.locations.empty()) {
            loc = r.locations[0].file + ":" + std::to_string(r.locations[0].line) + ":";
            if (r.locations[0].col > 0) loc += std::to_string(r.locations[0].col) + ":";
        }
        return loc + " (" + r.severity + ") " + r.message;
    }

    return applyTemplate(tmpl, r);
}

// ==================== FILE SYSTEM ====================

static bool isSourceFile(const std::string& filename) {
    static const std::set<std::string> exts = {
        ".cpp", ".cxx", ".cc", ".c++", ".c", ".ipp", ".ixx", ".tpp", ".txx"
    };
    size_t dot = filename.rfind('.');
    if (dot == std::string::npos) return false;
    std::string ext = filename.substr(dot);
    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
    return exts.count(ext) > 0;
}

static bool fileExists(const std::string& path) {
    struct stat st;
    return stat(path.c_str(), &st) == 0;
}

static bool isDirectory(const std::string& path) {
    struct stat st;
    if (stat(path.c_str(), &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

static std::vector<std::string> getFiles(const std::string& path) {
    std::vector<std::string> result;

    if (!isDirectory(path)) {
        if (fileExists(path)) result.push_back(path);
        return result;
    }

    // Recursively get source files
    std::vector<std::string> dirs;
    dirs.push_back(path);

    while (!dirs.empty()) {
        std::string dir = dirs.back();
        dirs.pop_back();

        DIR* d = opendir(dir.c_str());
        if (!d) continue;

        std::vector<std::string> entries;
        struct dirent* entry;
        while ((entry = readdir(d)) != nullptr) {
            std::string name = entry->d_name;
            if (name == "." || name == "..") continue;
            entries.push_back(name);
        }
        closedir(d);

        std::sort(entries.begin(), entries.end());

        for (const auto& name : entries) {
            std::string fullPath = dir + "/" + name;
            if (isDirectory(fullPath)) {
                dirs.push_back(fullPath);
            } else if (isSourceFile(fullPath)) {
                result.push_back(fullPath);
            }
        }
    }

    std::sort(result.begin(), result.end());
    return result;
}

