static ParseResult parseArgs(int argc, char* argv[], Settings& settings) {
    ParseResult result;

    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];

        if (arg == "--version") {
            result.showVersion = true;
        } else if (arg == "--help" || arg == "-h") {
            result.showHelp = true;
        } else if (arg == "--errorlist") {
            result.showErrorList = true;
        } else if (arg == "--xml") {
            settings.xml = true;
        } else if (arg == "-q" || arg == "--quiet") {
            settings.quiet = true;
        } else if (arg == "-v" || arg == "--verbose") {
            settings.verbose = true;
        } else if (arg == "-f" || arg == "--force") {
            settings.force = true;
        } else if (arg == "--inconclusive") {
            settings.inconclusive = true;
        } else if (arg == "--check-config") {
            settings.checkConfig = true;
        } else if (arg == "--check-library") {
            settings.checkLibrary = true;
        } else if (arg == "--inline-suppr") {
            settings.inlineSuppr = true;
        } else if (arg == "--report-progress") {
            settings.reportProgress = true;
        } else if (arg == "--dump") {
            settings.dump = true;
        } else if (arg == "--safety") {
            settings.safety = true;
            settings.checkLevel = "exhaustive";
            settings.inconclusive = true;
        } else if (arg == "-E") {
            settings.printE = true;
        } else if (arg == "--fsigned-char") {
            settings.fsignedChar = true;
        } else if (arg == "--funsigned-char") {
            settings.funsignedChar = true;
        } else if (arg.substr(0, 9) == "--enable=") {
            std::string enables = arg.substr(9);
            // Split by comma
            std::stringstream ss(enables);
            std::string item;
            while (std::getline(ss, item, ',')) {
                if (item == "all") {
                    settings.enabledChecks.insert("warning");
                    settings.enabledChecks.insert("style");
                    settings.enabledChecks.insert("performance");
                    settings.enabledChecks.insert("portability");
                    settings.enabledChecks.insert("information");
                    settings.enabledChecks.insert("unusedFunction");
                    settings.enabledChecks.insert("missingInclude");
                    settings.enabledChecks.insert("all");
                } else {
                    settings.enabledChecks.insert(item);
                    // "style" enables warning, performance, portability too
                    if (item == "style") {
                        settings.enabledChecks.insert("warning");
                        settings.enabledChecks.insert("performance");
                        settings.enabledChecks.insert("portability");
                    }
                }
            }
        } else if (arg.substr(0, 10) == "--disable=") {
            std::string disables = arg.substr(10);
