int main(int argc, char* argv[]) {
    Settings settings;

    ParseResult parsed = parseArgs(argc, argv, settings);

    // Handle special output commands first
    if (parsed.showVersion) {
        std::cout << "Cppcheck " << CPPCHECK_VERSION << "\n";
        return 0;
    }

    if (parsed.showHelp) {
        std::cout << HELP_TEXT;
        return 0;
    }

    if (parsed.showErrorList) {
        printErrorList(std::cout);
        return 0;
    }

    // No args (or only options) -> show help
    if (argc == 1) {
        std::cout << HELP_TEXT;
        return 0;
    }

    // Determine output stream for errors
    std::ostream* errOut = &std::cerr;
    std::ofstream outputFileStream;
    if (!settings.outputFile.empty()) {
        outputFileStream.open(settings.outputFile);
        if (outputFileStream.is_open()) {
            errOut = &outputFileStream;
        }
    }

    // If XML mode, errors go to stderr
    if (settings.xml) {
        errOut = &std::cerr;
    }

    // Check for paths  
    if (parsed.paths.empty() && settings.fileList.empty() && settings.projectFile.empty()) {
        if (settings.checkConfig) {
            std::cout << "cppcheck: error: no C or C++ source files found.\n";
            return 1;
        }
        // Show help if no paths
        std::cout << HELP_TEXT;
        return 0;
    }

    // Load std.cfg
    std::string stdCfgPath = std::string(FILESDIR) + "/cfg/std.cfg";
    std::ifstream stdCfgFile(stdCfgPath);
    if (!stdCfgFile.is_open()) {
        std::cout << "cppcheck: Failed to load library configuration file 'std.cfg'. File not found\n";
        std::cout << "Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. "
                  << "The Cppcheck binary was compiled with FILESDIR set to \"" << FILESDIR << "\" "
                  << "and will therefore search for std.cfg in " << FILESDIR << "/cfg.\n";
        return 1;
    }
    stdCfgFile.close();

    // Collect all files to check
    std::vector<std::string> filesToCheck;

    for (const auto& path : parsed.paths) {
        if (isDirectory(path)) {
            auto files = getFiles(path);
            filesToCheck.insert(filesToCheck.end(), files.begin(), files.end());
        } else if (fileExists(path)) {
            filesToCheck.push_back(path);
        } else {
            // File doesn't exist
            if (!settings.quiet) {
                std::cerr << "cppcheck: error: could not find or open any of the paths given.\n";
            }
        }
    }

    if (filesToCheck.empty() && parsed.paths.empty()) {
        return 0;
    }

    // XML output header
    if (settings.xml) {
        *errOut << "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
        *errOut << "<results version=\"2\">\n";
        *errOut << "    <cppcheck version=\"" << CPPCHECK_VERSION << "\"/>\n";
        *errOut << "    <errors>\n";
    }

    bool hasErrors = false;
    int totalFiles = filesToCheck.size();
    int checkedFiles = 0;

    for (const auto& filepath : filesToCheck) {
        checkedFiles++;

        // Progress reporting
        if (!settings.quiet) {
            std::cerr << "Checking " << filepath << "...\n";
            if (totalFiles > 1) {
                int pct = (checkedFiles * 100) / totalFiles;
                std::cerr << checkedFiles << "/" << totalFiles << " files checked " << pct << "% done\n";
            }
        }

        // Read file
        std::ifstream f(filepath);
        if (!f.is_open()) {
            continue;
        }
        std::string code((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());

        // Run analysis
        auto results = runAllChecks(filepath, code, settings);

        // Output results
        for (const auto& r : results) {
            if (!settings.isEnabled(r.severity) && r.severity != "error") continue;

            hasErrors = true;

            if (settings.xml) {
                *errOut << "    <error id=\"" << xmlEncode(r.id) << "\""
                        << " severity=\"" << xmlEncode(r.severity) << "\""
                        << " msg=\"" << xmlEncode(r.message) << "\""
                        << " verbose=\"" << xmlEncode(r.verbose.empty() ? r.message : r.verbose) << "\"";
                if (!r.cwe.empty()) *errOut << " cwe=\"" << xmlEncode(r.cwe) << "\"";
                *errOut << ">\n";
                for (const auto& loc : r.locations) {
                    *errOut << "        <location file=\"" << xmlEncode(loc.file) << "\""
                            << " line=\"" << loc.line << "\"";
                    if (loc.col > 0) *errOut << " column=\"" << loc.col << "\"";
                    *errOut << "/>\n";
                }
                *errOut << "    </error>\n";
            } else {
                *errOut << formatError(r, settings) << "\n";
                if (settings.verbose && r.verbose != r.message) {
                    // Print verbose message too
                    *errOut << r.verbose << "\n";
                }
            }
        }
    }

    // XML footer
    if (settings.xml) {
        *errOut << "    </errors>\n";
        *errOut << "</results>\n";
    }

    // Return code
    if (hasErrors && settings.errorExitCode != 0) {
        return settings.errorExitCode;
    }

    return 0;
}
